"""Durable OperationStore adapters for the original Alpha Zoo tools."""

from __future__ import annotations

import json
import re
from typing import Any

from fastapi import HTTPException

_ALPHA_ID = re.compile(r"^[a-z][a-z0-9]+_[a-z0-9_]{1,64}$")
_ZOO = frozenset({"alpha101", "gtja191", "qlib158", "academic", "fundamental"})
_UNIVERSE = frozenset({"csi300", "sp500", "btc-usdt"})
_SORT = frozenset({"ir", "ic_mean", "ic_positive_ratio", "ic_count"})


def _period(value: Any) -> str:
    if not isinstance(value, str) or len(value) > 32:
        raise HTTPException(status_code=422, detail="period must use a native Alpha Zoo range")
    try:
        from src.tools.alpha_bench_tool import _parse_period

        start, end = _parse_period(value)
    except (ImportError, ValueError, TypeError, OverflowError) as exc:
        raise HTTPException(status_code=422, detail="period must use YYYY-YYYY or YYYY-MM-DD/YYYY-MM-DD") from exc
    if not start or not end:
        raise HTTPException(status_code=422, detail="period is invalid")
    return value


def _positive_integer(value: Any, field: str, *, maximum: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or not 1 <= value <= maximum:
        raise HTTPException(status_code=422, detail=f"{field} must be an integer from 1 to {maximum}")
    return value


def _alpha_id(value: Any) -> str:
    if not isinstance(value, str) or not _ALPHA_ID.fullmatch(value):
        raise HTTPException(status_code=422, detail="alpha_id is invalid")
    return value


def validate_alpha_operation(operation: str, payload: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any]]:
    """Validate a durable request against the original AlphaZoo REST contract."""
    if operation not in {"alpha_bench", "alpha_compare"} or not isinstance(payload, dict):
        raise HTTPException(status_code=422, detail="unsupported Alpha Zoo operation")
    if payload.get("operation", operation) != operation:
        raise HTTPException(status_code=422, detail="operation name does not match the Alpha Zoo request")
    clean = {key: value for key, value in payload.items() if key != "operation"}

    if operation == "alpha_bench":
        required = {"zoo", "universe", "period"}
        optional = {"alpha_id", "top"}
        if not required <= clean.keys() or clean.keys() - required - optional:
            raise HTTPException(status_code=422, detail="Alpha bench fields do not match the native API")
        if not isinstance(clean["zoo"], str) or clean["zoo"] not in _ZOO:
            raise HTTPException(status_code=422, detail="zoo is not registered by Alpha Zoo")
        if not isinstance(clean["universe"], str) or clean["universe"] not in _UNIVERSE:
            raise HTTPException(status_code=422, detail="universe is not supported by Alpha Zoo")
        clean["period"] = _period(clean["period"])
        if "alpha_id" in clean:
            clean["alpha_id"] = _alpha_id(clean["alpha_id"])
            from src.factors.registry import get_default_registry

            try:
                selected = get_default_registry().get(clean["alpha_id"])
            except KeyError as exc:
                raise HTTPException(status_code=422, detail="alpha_id is not registered by Alpha Zoo") from exc
            if selected.zoo != clean["zoo"]:
                raise HTTPException(status_code=422, detail="alpha_id does not belong to the selected zoo")
        clean["top"] = _positive_integer(clean.get("top", 20), "top", maximum=500)
        reference = {key: clean[key] for key in ("universe", "period", "alpha_id", "zoo") if key in clean}
        return clean, reference

    required = {"alpha_ids", "universe", "period"}
    optional = {"sort"}
    if not required <= clean.keys() or clean.keys() - required - optional:
        raise HTTPException(status_code=422, detail="Alpha compare fields do not match the native tool")
    ids = clean["alpha_ids"]
    if not isinstance(ids, list) or not 2 <= len(ids) <= 50:
        raise HTTPException(status_code=422, detail="alpha_ids must contain 2 to 50 factors")
    normalized = list(dict.fromkeys(_alpha_id(item) for item in ids))
    if len(normalized) < 2:
        raise HTTPException(status_code=422, detail="alpha_ids must contain at least two distinct factors")
    clean["alpha_ids"] = normalized
    if not isinstance(clean["universe"], str) or clean["universe"] not in _UNIVERSE:
        raise HTTPException(status_code=422, detail="universe is not supported by Alpha Zoo")
    clean["period"] = _period(clean["period"])
    clean.setdefault("sort", "ir")
    if not isinstance(clean["sort"], str) or clean["sort"] not in _SORT:
        raise HTTPException(status_code=422, detail="sort is not supported by Alpha Zoo")
    return clean, {"alpha_ids": normalized, "universe": clean["universe"], "period": clean["period"]}


def alpha_defaults() -> dict[str, Any]:
    """Project the original AlphaZoo request schemas and registered factor counts."""
    from src.api.alpha_routes import (
        _BENCH_UNIVERSES,
        _VALID_SORTS,
        _VALID_ZOOS,
        BenchRequest,
        CompareRequest,
    )
    from src.factors.registry import get_default_registry

    registry = get_default_registry()
    zoo_counts = {zoo: len(registry.list(zoo=zoo)) for zoo in sorted(_VALID_ZOOS)}
    bench_schema = BenchRequest.model_json_schema()
    compare_schema = CompareRequest.model_json_schema()
    for schema in (bench_schema, compare_schema):
        schema.get("properties", {}).pop("request_id", None)
    bench_schema["properties"]["zoo"]["enum"] = sorted(_VALID_ZOOS)
    bench_schema["properties"]["universe"]["enum"] = sorted(_BENCH_UNIVERSES)
    compare_schema["properties"]["universe"]["enum"] = sorted(_BENCH_UNIVERSES)
    compare_schema["properties"]["sort"]["enum"] = sorted(_VALID_SORTS)
    return {
        "bench": {"operation": "alpha_bench", "request_schema": bench_schema},
        "compare": {"operation": "alpha_compare", "request_schema": compare_schema},
        "registry": {"total": sum(zoo_counts.values()), "zoo_counts": zoo_counts},
    }


def run_alpha_operation(
    operation: str,
    payload: dict[str, Any],
    progress=None,
) -> tuple[str, dict[str, Any]]:
    """Execute the original AlphaZoo engines and report their actual progress."""
    clean, references = validate_alpha_operation(operation, payload)
    on_progress = None
    on_stage = None
    if progress is not None:
        def on_progress(n_done, n_total, alpha_id):
            progress({"n_done": n_done, "n_total": n_total, "current_alpha_id": alpha_id})

        def on_stage(stage):
            progress({"stage": stage})

    if operation == "alpha_bench":
        from src.api.alpha_routes import _result_for_wire
        from src.factors.bench_runner import run_bench

        result = run_bench(
            zoo=clean["zoo"],
            universe=clean["universe"],
            period=clean["period"],
            top=clean["top"],
            only=[clean["alpha_id"]] if clean.get("alpha_id") else None,
            on_progress=on_progress,
            on_stage=on_stage,
        )
        wire = _result_for_wire(result)
        wire["status"] = result.get("status")
        if result.get("error") is not None:
            wire["error"] = result["error"]
        references["top_alpha_ids"] = [
            row["id"] for row in wire.get("top5_by_ir", [])
            if isinstance(row, dict) and isinstance(row.get("id"), str)
        ]
    elif operation == "alpha_compare":
        from src.api.alpha_routes import _compare_result_for_wire
        from src.factors.compare_runner import compare_alphas

        result = compare_alphas(
            clean["alpha_ids"],
            clean["universe"],
            clean["period"],
            sort=clean["sort"],
            on_progress=on_progress,
            on_stage=on_stage,
        )
        wire = _compare_result_for_wire(result)
        wire["status"] = result.get("status")
        if result.get("error") is not None:
            wire["error"] = result["error"]
    else:
        raise HTTPException(status_code=422, detail="unsupported Alpha Zoo operation")
    return json.dumps(wire, ensure_ascii=False, allow_nan=False), references

