from __future__ import annotations

import json
import sys
from types import ModuleType

import pytest
from fastapi import HTTPException
from src.api.mona_alpha_operations import (
    alpha_defaults,
    run_alpha_operation,
    validate_alpha_operation,
)


def test_alpha_bench_uses_the_native_tool_arguments_and_references(monkeypatch):
    runner = ModuleType("src.factors.bench_runner")
    observed = {}

    def run_bench(**kwargs):
        observed.update(kwargs)
        kwargs["on_stage"]("loading")
        kwargs["on_progress"](1, 1, "alpha101_001")
        return {
            "status": "ok", "zoo": "alpha101", "universe": "csi300", "period": "2020-2024",
            "n_alphas_tested": 1, "n_skipped": 0, "alive": 1, "reversed": 0, "dead": 0,
            "top5_by_ir": [{"id": "alpha101_001"}], "dead_examples": [], "by_theme": {}, "meta": {},
            "rows": [{"id": "alpha101_001"}], "skipped": [], "wall_seconds": 0.1,
        }

    runner.run_bench = run_bench
    monkeypatch.setitem(sys.modules, "src.factors.bench_runner", runner)
    payload = {"operation": "alpha_bench", "zoo": "alpha101", "universe": "csi300", "period": "2020-2024", "top": 10}
    progress = []
    raw, references = run_alpha_operation("alpha_bench", payload, progress=progress.append)
    assert observed == {
        "zoo": "alpha101", "universe": "csi300", "period": "2020-2024", "top": 10,
        "only": None, "on_progress": observed["on_progress"], "on_stage": observed["on_stage"],
    }
    result = json.loads(raw)
    assert result["status"] == "ok" and result["alive"] == 1 and result["top5_by_ir"][0]["id"] == "alpha101_001"
    assert "rows" not in result and result["skipped"] == 0 and "wall_seconds" not in result
    assert progress == [{"stage": "loading"}, {"n_done": 1, "n_total": 1, "current_alpha_id": "alpha101_001"}]
    assert references == {"universe": "csi300", "period": "2020-2024", "zoo": "alpha101",
                         "top_alpha_ids": ["alpha101_001"]}


def test_alpha_compare_uses_the_native_tool_arguments(monkeypatch):
    runner = ModuleType("src.factors.compare_runner")
    observed = {}

    def compare_alphas(*args, **kwargs):
        observed["args"] = args
        observed["kwargs"] = kwargs
        kwargs["on_stage"]("ranking")
        kwargs["on_progress"](1, 2, "alpha101_001")
        return {"status": "ok", "universe": "sp500", "period": "2020-2024", "sort": "ic_mean",
                "ranking": [], "skipped": [], "n_compared": 0}

    runner.compare_alphas = compare_alphas
    monkeypatch.setitem(sys.modules, "src.factors.compare_runner", runner)
    payload = {"operation": "alpha_compare", "alpha_ids": ["alpha101_001", "gtja191_2"],
               "universe": "sp500", "period": "2020-01-01/2024-12-31", "sort": "ic_mean"}
    progress = []
    raw, references = run_alpha_operation("alpha_compare", payload, progress=progress.append)
    assert observed["args"] == (payload["alpha_ids"], "sp500", "2020-01-01/2024-12-31")
    assert observed["kwargs"]["sort"] == "ic_mean"
    assert json.loads(raw)["status"] == "ok"
    assert progress == [{"stage": "ranking"}, {"n_done": 1, "n_total": 2, "current_alpha_id": "alpha101_001"}]
    assert references == {key: payload[key] for key in ("alpha_ids", "universe", "period")}


@pytest.mark.parametrize("operation,payload", [
    ("alpha_bench", {"universe": "csi300", "period": "2020-2024", "zoo": "alpha101", "alpha_id": "bad.id"}),
    ("alpha_bench", {"zoo": "unknown", "universe": "csi300", "period": "2020-2024"}),
    ("alpha_bench", {"universe": "csi300", "period": "2020-2024", "zoo": "alpha101", "top": True}),
    ("alpha_bench", {"zoo": "alpha101", "universe": "csi300", "period": "2020-2024", "output_dir": "../outside"}),
    ("alpha_compare", {"alpha_ids": ["alpha101_1", "alpha101_1"], "universe": "csi300", "period": "2020-2024"}),
    ("alpha_compare", {"alpha_ids": ["alpha101_1"], "universe": "csi300", "period": "2020-2024"}),
    ("alpha_compare", {"alpha_ids": ["alpha101_1", "gtja191_2"], "universe": "csi300", "period": "2020-2024", "path": "../outside"}),
    ("alpha_compare", {"alpha_ids": ["alpha101_1", "gtja191_2"], "universe": "csi300", "period": "2020-2024", "sort": "report_path"}),
])
def test_alpha_operations_reject_invalid_or_untrusted_fields(operation, payload):
    with pytest.raises(HTTPException):
        validate_alpha_operation(operation, {"operation": operation, **payload})


def test_alpha_operations_preserve_native_defaults_by_omitting_unset_values():
    clean, _ = validate_alpha_operation(
        "alpha_bench", {"operation": "alpha_bench", "zoo": "alpha101", "universe": "csi300", "period": "2020-2024"}
    )
    assert clean == {"zoo": "alpha101", "universe": "csi300", "period": "2020-2024", "top": 20}


def test_alpha_defaults_exposes_original_tool_schemas_and_registered_counts(monkeypatch):
    import src.factors.registry as registry_module
    from src.api.alpha_routes import BenchRequest, CompareRequest

    class Registry:
        def list(self, *, zoo):
            return [zoo + "_one", zoo + "_two"]

    monkeypatch.setattr(registry_module, "get_default_registry", lambda: Registry())
    result = alpha_defaults()
    assert result["bench"]["request_schema"]["properties"]["top"]["default"] == BenchRequest.model_fields["top"].default == 20
    assert "request_id" not in result["bench"]["request_schema"]["properties"]
    assert result["compare"]["request_schema"]["properties"]["sort"]["default"] == CompareRequest.model_fields["sort"].default == "ir"
    assert result["registry"] == {
        "total": 10,
        "zoo_counts": {zoo: 2 for zoo in ("academic", "alpha101", "fundamental", "gtja191", "qlib158")},
    }
